#include "core/ReleaseSignature.h"

#include <mbedtls/asn1.h>
#include <mbedtls/ecdsa.h>
#include <mbedtls/ecp.h>
#include <mbedtls/sha256.h>

// Mbed TLS built with cmake/vd_mbedtls_config.h, not with its full default configuration (see that file).
#if !defined(VD_MBEDTLS_CONFIG)
#error "Mbed TLS is not configured by cmake/vd_mbedtls_config.h"
#endif

#include <array>
#include <vector>

// Generated by CMake (cmake/ReleaseKey.h.in) from release/release-key.pub.hex.
#include "vd_release_key.gen.h"

namespace vd {

namespace {

static_assert(sizeof(kReleaseKeyPoint) == kReleaseKeySize);

// A DER ECDSA-Sig-Value over P-256 is at most 72 bytes; its base64, 96 characters.
constexpr usize kMaxSignatureBase64 = 128;

bool isSpace(char c) {
    return c == ' ' || c == '\t' || c == '\r' || c == '\n';
}

std::string_view trimmed(std::string_view text) {
    while (!text.empty() && isSpace(text.front())) {
        text.remove_prefix(1);
    }
    while (!text.empty() && isSpace(text.back())) {
        text.remove_suffix(1);
    }
    return text;
}

int base64Digit(char c) {
    if (c >= 'A' && c <= 'Z') {
        return c - 'A';
    }
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 26;
    }
    if (c >= '0' && c <= '9') {
        return c - '0' + 52;
    }
    if (c == '+') {
        return 62;
    }
    if (c == '/') {
        return 63;
    }
    return -1;
}

// Standard base64 with its padding (what openssl and .NET write); false for anything else.
bool decodeBase64(std::string_view text, std::vector<u8>& out) {
    if (text.empty() || text.size() % 4 != 0) {
        return false;
    }
    usize padding = 0;
    if (text.back() == '=') {
        padding = text[text.size() - 2] == '=' ? 2 : 1;
    }
    out.clear();
    out.reserve(text.size() / 4 * 3);
    for (usize i = 0; i < text.size(); i += 4) {
        const bool last = i + 4 == text.size();
        u32 group = 0;
        for (usize j = 0; j < 4; ++j) {
            const bool pad = last && j >= 4 - padding;
            const int digit = pad ? 0 : base64Digit(text[i + j]);
            if (digit < 0) {
                return false;
            }
            group = group << 6 | static_cast<u32>(digit);
        }
        out.push_back(static_cast<u8>(group >> 16));
        if (!last || padding < 2) {
            out.push_back(static_cast<u8>(group >> 8));
        }
        if (!last || padding < 1) {
            out.push_back(static_cast<u8>(group));
        }
    }
    return true;
}

// The Mbed TLS objects of one verification, freed on every way out.
struct Verifier {
    mbedtls_ecp_group group;
    mbedtls_ecp_point key;
    mbedtls_mpi r;
    mbedtls_mpi s;

    Verifier() {
        mbedtls_ecp_group_init(&group);
        mbedtls_ecp_point_init(&key);
        mbedtls_mpi_init(&r);
        mbedtls_mpi_init(&s);
    }
    ~Verifier() {
        mbedtls_mpi_free(&s);
        mbedtls_mpi_free(&r);
        mbedtls_ecp_point_free(&key);
        mbedtls_ecp_group_free(&group);
    }
    Verifier(const Verifier&) = delete;
    Verifier& operator=(const Verifier&) = delete;
};

} // namespace

std::span<const u8, kReleaseKeySize> releasePublicKey() {
    return std::span<const u8, kReleaseKeySize>(kReleaseKeyPoint, kReleaseKeySize);
}

bool verifyRelease(std::span<const u8> manifest, std::string_view signatureBase64) {
    return verifyRelease(manifest, signatureBase64, releasePublicKey());
}

bool verifyRelease(std::span<const u8> manifest, std::string_view signatureBase64,
                   std::span<const u8> publicKey) {
    if (publicKey.size() != kReleaseKeySize || publicKey[0] != 0x04) {
        return false; // only the uncompressed form
    }
    const std::string_view text = trimmed(signatureBase64);
    std::vector<u8> der;
    if (text.size() > kMaxSignatureBase64 || !decodeBase64(text, der)) {
        return false;
    }

    Verifier verifier;
    const u8* const point = publicKey.data();
    if (mbedtls_ecp_group_load(&verifier.group, MBEDTLS_ECP_DP_SECP256R1) != 0 ||
        mbedtls_ecp_point_read_binary(&verifier.group, &verifier.key, point, kReleaseKeySize) != 0 ||
        mbedtls_ecp_check_pubkey(&verifier.group, &verifier.key) != 0) {
        return false; // not a point of the curve
    }
    // ECDSA-Sig-Value ::= SEQUENCE { r INTEGER, s INTEGER }, nothing after it.
    u8* cursor = der.data();
    u8* const end = der.data() + der.size();
    usize length = 0;
    if (mbedtls_asn1_get_tag(&cursor, end, &length, MBEDTLS_ASN1_CONSTRUCTED | MBEDTLS_ASN1_SEQUENCE) != 0 ||
        cursor + length != end || mbedtls_asn1_get_mpi(&cursor, end, &verifier.r) != 0 ||
        mbedtls_asn1_get_mpi(&cursor, end, &verifier.s) != 0 || cursor != end) {
        return false;
    }

    std::array<u8, 32> digest{};
    if (mbedtls_sha256(manifest.data(), manifest.size(), digest.data(), 0) != 0) {
        return false;
    }
    return mbedtls_ecdsa_verify(&verifier.group, digest.data(), digest.size(), &verifier.key, &verifier.r,
                                &verifier.s) == 0;
}

} // namespace vd
